/* @autogenerated */
import { MFE_REMOTES_GLOBAL, MfeConfigAdapter } from './mfe-config.adapter';

describe('MfeConfigAdapter', () => {
  const adapter = new MfeConfigAdapter();

  afterEach(() => delete (window as any)[MFE_REMOTES_GLOBAL]);

  it('without a registered remote has no config URL and reads i18n relative to the app', () => {
    expect(adapter.configUrl('app')).toBeUndefined();
    expect(adapter.i18nBase('app')).toBe('i18n');
  });

  it('resolves config and i18n from the registered remote', () => {
    adapter.register('app', 'https://cdn.example.com/', 'config.json');

    expect(adapter.configUrl('app')).toBe('https://cdn.example.com/config.json');
    expect(adapter.i18nBase('app')).toBe('https://cdn.example.com/i18n');
    expect(adapter.configUrl('other')).toBeUndefined();
  });
});
